public int sockMerchant(int n, List<Integer> ar) {
    Map<Integer, Integer> count = new HashMap<>();
    for (int color : ar) {
        count.merge(color, 1, Integer::sum);
    }
    int pairs = 0;
    for (int c : count.values()) {
        pairs += c / 2;
    }
    return pairs;
}

